-- reports/crash-for-addition
-- The crash a visitor chose in "Is it one of these?"; must exist and not be rejected or merged.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "rejected"
--   $3 = "merged"
--   $4 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/reports.ts. Do not edit by hand.

select "id", "slug"
from "crashes"
where ("crashes"."id" = $1
  and "crashes"."status" not in ($2, $3))
limit $4;
